    30→  if (typeof js === "number") {
    31→    return Number.isInteger(js) ? V.i32(js) : V.f64(js);
    32→  }
    33→  if (Array.isArray(js)) {
    34→    return V.arr(js.map(jsToValue));
    35→  }
