    12→import { Actor, ActorState } from '../types';
    13→
    14→let actorIdCounter = 0;
    15→let totalInstructions = 0;
    16→
    17→/**
    18→ * Actor 생성
    19→ * @param fn 실행할 비동기 함수
    20→ * @param args 함수에 전달할 인자
    21→ * @returns Actor 객체 (실행 중)
    22→ */
    23→export async function spawn<T>(
    24→  fn: (...args: any[]) => Promise<T> | T,
    25→  ...args: any[]
    26→): Promise<Actor<T>> {
    27→  const actor: Actor<T> = {
    28→    id: `actor_${++actorIdCounter}`,
    29→    state: ActorState.CREATED,
    30→    fn: async () => {
    31→      const result = fn(...args);
    32→      return result instanceof Promise ? result : result;
    33→    },
    34→    result: undefined,
    35→    error: undefined,
    36→    startTime: Date.now(),
    37→    executedInstructions: 0,
    38→    lastYieldTime: Date.now()
    39→  };
    40→
    41→  // 비동기로 실행 시작 (이벤트 루프에 등록)
    42→  setImmediate(async () => {
    43→    try {
    44→      actor.state = ActorState.RUNNING;
    45→      const result = await actor.fn();
    46→      actor.result = result;
    47→      actor.state = ActorState.COMPLETED;
    48→      totalInstructions += actor.executedInstructions;
    49→    } catch (error) {
    50→      actor.error = error instanceof Error ? error : new Error(String(error));
    51→      actor.state = ActorState.FAILED;
    52→    }
    53→  });
    54→
    55→  // Actor 객체 반환 (실행은 백그라운드에서 계속)
    56→  return actor;
