    12→import { Actor, ActorState, WaitResult } from '../types';
    13→
    14→/**
    15→ * WaitGroup - 여러 Actor 동시 대기
    16→ */
    17→export class WaitGroup<T = any> {
    18→  private actors: Actor<T>[] = [];
    19→  private activeCount = 0;
    20→
    21→  add(actor: Actor<T>) {
    22→    this.actors.push(actor);
    23→    this.activeCount++;
    24→  }
    25→
    26→  addMany(actors: Actor<T>[]) {
    27→    this.actors.push(...actors);
    28→    this.activeCount += actors.length;
    29→  }
    30→
    31→  async wait(): Promise<WaitResult<T>> {
    32→    const completed: T[] = [];
    33→    const failed: Error[] = [];
    34→    const cancelled: string[] = [];
    35→
    36→    // 모든 Actor 완료 대기
    37→    const promises = this.actors.map(async (actor) => {
    38→      try {
    39→        // Actor 상태 체크 (500ms마다)
    40→        while (
    41→          actor.state !== ActorState.COMPLETED &&
    42→          actor.state !== ActorState.FAILED
    43→        ) {
    44→          await new Promise((resolve) => setTimeout(resolve, 50));
    45→        }
    46→
    47→        if (actor.state === ActorState.COMPLETED) {
    48→          if (actor.result !== undefined) {
    49→            completed.push(actor.result);
    50→          }
    51→        } else if (actor.state === ActorState.FAILED) {
    52→          if (actor.error) {
    53→            failed.push(actor.error);
    54→          }
    55→        }
    56→      } catch (error) {
    57→        cancelled.push(actor.id);
    58→      }
    59→    });
