     1→/**
     2→ * 5. sleep - 일시 정지 (Yield)
     3→ *
     4→ * 현재 태스크를 지정된 시간 동안 멈추지만, 시스템 전체를 멈추지 않습니다.
     5→ *
     6→ * 특징:
     7→ * - CPU 자원을 점유하지 않고 스케줄러에게 실행 권한을 양보
     8→ * - 효율적인 자원 분배와 타이밍 제어
     9→ * - Cooperative multitasking의 핵심
    10→ */
    11→
    12→/**
    13→ * 지정된 시간 동안 현재 task 일시 정지
    14→ * (시스템 전체는 계속 작동)
    15→ *
    16→ * @param ms 대기 시간 (밀리초)
    17→ *
    18→ * @example
    19→ * async function task() {
    20→ *   console.log('Start');
    21→ *   await sleep(1000);  // 1초 대기
    22→ *   console.log('After 1s');
    23→ * }
    24→ */
    25→export function sleep(ms: number): Promise<void> {
    26→  if (ms < 0) {
    27→    return Promise.reject(new Error('sleep duration cannot be negative'));
    28→  }
    29→
    30→  if (ms === 0) {
